/**
 * Error：错误响应体结构。restwire.WriteErrCode 序列化此 message 为 JSON。
 * 与现有手工拼接 `{"error_code":"...","error":"..."}` 线格式一致；
 * error_code 字段 protojson 输出 enum 值名（小写下划线），error 字段输出本地化文案。
 * publish_id 仅发布链路 WriteErrWithPubIDCode 使用，空值按 protojson 省略。
 */
export interface Error {
  errorCode: ErrorCode;
  error: string;
  publishId: string;
}
